def main():
    import sys
    path=ROOT/('tool/staging/maps.json' if '--staged' in sys.argv else 'assets/questions/maps.json');raw=path.read_bytes();bank=json.loads(raw.decode('utf-8'))
    new={}
    for i,(t,a,w,h,e) in enumerate(E,206):new[f'maps-easy-{i:04}']=problem(t,a,w.split('|'),h,e)
    mapped_wrong={202:[12500,25000,75000,100000,200000],203:[500,600,700,900,1000],210:[20,30,50,60,80],212:[0,2,3,4,5],214:[90,180,225,315,360],220:[150,180,195,240,270],221:[350,500,600,800,1000]}
    for i,(t,a,h,e,u) in enumerate(M,201):
        if i in mapped_wrong:new[f'maps-medium-{i:04}']=problem(t,str(a)+u,[str(w)+u for w in mapped_wrong[i]],h,e)
        else:new[f'maps-medium-{i:04}']=numeric(t,a,h,e,u)
    for q in bank['questions']:
        if q['id'] in new:
            x=new[q['id']];x.pop('_proof',None);q.clear();q.update(id=next(k for k,v in new.items() if v is x),categoryId='maps',difficulty='easy' if x in [new[k] for k in new if '-easy-' in k] else 'medium',**x)
    # Remove stale generated-proof entries only for rewritten additions.
    lp=ROOT/'tool/reasoning_proofs.json';led=json.loads(lp.read_text(encoding='utf-8'));lp.write_text(json.dumps([p for p in led if p['id'] not in new],ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    assert path.read_bytes()==raw
    path.write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('45 distinct map tasks replace walk variants.')
if __name__=='__main__':main()
